from pathlib import Path
import json,html,collections,re,hashlib,datetime
b=Path(__file__).resolve().parent
rows=json.loads((b/'requirements-audit.json').read_text(encoding='utf-8'))
labels={'محلي':'مطبق في المحاكاة','جزئي':'مطبق جزئيًا','ناقص':'ناقص في الواجهة/الدورة','مخالف':'سلوك يخالف المرجع','قرار':'مستثنى بطلبك','ربط':'يتطلب ربطًا فعليًا','معلق':'غير محسوم / مقترح — ليس نقصًا مؤكدًا'}
colors={'محلي':'ok','جزئي':'partial','ناقص':'missing','مخالف':'conflict','قرار':'decision','ربط':'backend','معلق':'pending'}
counts=collections.Counter(r['status'] for r in rows)
e=html.escape
source=(b/'updated-requirements.txt').read_text(encoding='utf-8')
sources={int(line.split(' ',1)[0]):line.split(' ',1)[1] for line in source.splitlines() if re.match(r'^\d+ ',line)}
def source_link(s):
    n=re.search(r'\d+',s)
    return f'<a href="#p{n[0]}" class="source-ref" data-p="{n[0]}">فقرات {e(s)}</a>' if n else e(s)
cards=[]
for r in rows:
    cards.append(f'''<article class="requirement" data-state="{e(r['status'])}" data-module="{e(r['module'])}" id="{r['id']}">
    <div class="rowtop"><span class="code">{r['id']} · {e(r['module'])}</span><span class="badge {colors[r['status']]}">{labels[r['status']]}</span></div>
    <h3>{e(r['requirement'])}</h3><div class="where">مكان الفحص: <strong>{e(r['page'])}</strong></div><p>{e(r['finding'])}</p>
    <details><summary>المصدر ودليل الفحص</summary><p><strong>أساس الحكم:</strong> {e(r['basis'])}</p><p>{source_link(r['source'])} من المستند المحدث. أرقام الفقرات تخص نسخة الاستخراج وليست أرقام صفحات Word.</p><p class="evidence">{e(r['evidence'])}</p></details></article>''')
stats=''.join(f'<button class="stat {colors[k]}" data-filter="{k}"><b>{counts[k]}</b><span>{v}</span></button>' for k,v in labels.items())
mods=''.join(f'<option>{e(m)}</option>' for m in dict.fromkeys(r['module'] for r in rows))
paras=''.join(f'<p id="p{n}"><b>{n:03}</b> {e(t)}</p>' for n,t in sources.items())
inventory=json.loads((b/'video/inventory.json').read_text(encoding='utf-8'))
video_cards=[]
for v in inventory:
    done=(b/f'video/video-{v["id"]}-transcript.done').exists()
    original=(Path('E:/فيديوات اجتماعات ماسال')/v['file']).as_uri()
    video_cards.append(f'<article><h3><a href="{e(original)}">{e(v["file"])}</a></h3><p>{v["minutes"]} دقيقة · '+('التفريغ الآلي كامل المدة، مع أخطاء ومقاطع غير مفهومة.' if done else 'التفريغ الآلي قيد المعالجة.')+f'</p><a href="video/video-{v["id"]}-overview.jpg"><img loading="lazy" src="video/video-{v["id"]}-overview.jpg" alt="لقطات متباعدة من التسجيل {v["id"]}"></a></article>')
video_notes=(b/'video-findings.html').read_text(encoding='utf-8') if (b/'video-findings.html').exists() else '<p>لم تُضف بعد إحالات التسجيلات النهائية؛ هذا القسم قيد المراجعة.</p>'
proof=json.loads((b/'verified-gaps.json').read_text())
snapshot={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in b.parent.glob('*.js')}
snapshot['masal.html']=hashlib.sha256((b.parent/'masal.html').read_bytes()).hexdigest()
(b/'reviewed-build-sha256.json').write_text(json.dumps(snapshot,indent=2))
